// site/astro.config.mjs - Astro + Starlight configuration for the website.
// The pages themselves are generated by scripts/generate.mjs (see README.md).
// Starlight options: https://starlight.astro.build/reference/configuration/
import starlight from '@astrojs/starlight';
import { defineConfig } from 'astro/config';
import { starlightLocales, translatedLabel } from './i18n.mjs';
import { satteri } from '@astrojs/markdown-satteri';
import academic from './plugins/academic.mjs';

// SITE_BASE is the URL path the site is served under. "/" works for a local
// preview and a custom domain; a GitHub Pages project site needs
// "/<repo>/". https://docs.astro.build/en/reference/configuration-reference/#base
const base = process.env.SITE_BASE || '/';
// SITE_URL is the origin the site is published at, without the base path
// (for GitHub Pages: https://<owner>.github.io). Astro needs it for the
// canonical link of each page, and Starlight for the sitemap:
// https://starlight.astro.build/guides/customization/#enable-sitemap
// The default fits a local preview.
const site = process.env.SITE_URL || 'http://localhost:4321';

// A menu entry: its label comes from site-ui.yml, in every locale. Starlight
// adds the locale prefix (/pt-br/...) to the link by itself.
const link = (key, href) => ({ ...translatedLabel(key), link: href });
const title = translatedLabel('site.title');

export default defineConfig({
  site,
  base,
  // Numbered tables and figures, bibliography-style Sources lists. Sätteri
  // is Astro 7's Markdown processor; Starlight adds its own plugins to it.
  // Sätteri plugins: https://satteri.bruits.org/docs/
  markdown: { processor: satteri({ hastPlugins: [academic] }) },
  // No anonymous usage data is sent from builds: https://astro.build/telemetry/
  // (scripts/build-site.sh also sets ASTRO_TELEMETRY_DISABLED=1).
  integrations: [
    starlight({
      // The title per language tag: https://starlight.astro.build/guides/i18n/#translate-the-site-title
      title: { en: title.label, ...title.translations },
      // The <meta name="description"> of pages that have none of their own.
      description: translatedLabel('site.description').label,
      // Fonts are bundled with the site (Fontsource packages), never loaded
      // from a font CDN, so a visit contacts no third-party server.
      customCss: [
        '@fontsource-variable/source-serif-4',
        '@fontsource-variable/source-sans-3',
        '@fontsource-variable/jetbrains-mono',
        './src/styles/theme.css',
        './src/styles/site.css',
      ],
      // Overridden components: https://starlight.astro.build/guides/overriding-components/
      // Hero: Starlight shows no "not translated" notice on splash pages
      // (Home); this override adds it. SiteTitle: a short title on narrow
      // screens. SocialIcons: the header links to the main sections.
      // PageTitle: a breadcrumb above the title of language and
      // implementation pages.
      components: {
        Hero: './src/components/Hero.astro',
        SiteTitle: './src/components/SiteTitle.astro',
        SocialIcons: './src/components/SocialIcons.astro',
        PageTitle: './src/components/PageTitle.astro',
      },
      // Fence names used in the Markdown that Shiki does not know: the same
      // ids as for the source files in scripts/generate.mjs (QB64 BASIC and
      // Eiffel have no Shiki grammar, so they stay plain text).
      // https://expressive-code.com/key-features/syntax-highlighting/#langalias
      expressiveCode: {
        shiki: { langAlias: { nasm: 'asm', fortran: 'fortran-free-form', basic: 'txt', eiffel: 'txt' } },
      },
      // English at the root URL, other languages under /<dir>/ (site/i18n.mjs).
      // With two or more locales Starlight shows a language picker.
      // https://starlight.astro.build/guides/i18n/
      defaultLocale: 'root',
      locales: starlightLocales(),
      // The menu: reader pages first, then the reference pages.
      sidebar: [
        link('nav.home', '/'),
        link('nav.startHere', '/start-here/'),
        {
          ...translatedLabel('nav.languages'),
          items: [
            link('nav.allLanguages', '/languages/'),
            link('nav.implementations', '/implementations/'),
            link('nav.timeline', '/timeline/'),
            link('nav.genealogy', '/genealogy/'),
            { ...translatedLabel('nav.byLanguage'), collapsed: true, items: [{ autogenerate: { directory: 'languages', collapsed: true } }] },
          ],
        },
        {
          ...translatedLabel('nav.compareGroup'),
          items: [
            link('nav.compare', '/compare/'),
            link('nav.sideBySide', '/compare/side-by-side/'),
            link('nav.facts', '/facts/'),
          ],
        },
        link('nav.paradigms', '/paradigms/'),
        link('nav.aiEssay', '/ai-essay/'),
        link('nav.sources', '/sources/'),
        link('nav.platformSupport', '/platform-support/'),
        link('nav.contributing', '/contributing/'),
        link('nav.about', '/about/'),
        link('nav.offTheRecord', '/off-the-record/'),
      ],
    }),
  ],
});
